package yagen.waitmydawn.mkb_export.client;
import com.google.gson.*;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.phys.Vec3;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.SynchedEntityData;
import java.util.*;
import yagen.waitmydawn.mkb_export.core.*;

final class EntityComposition {
    record Node(String key,String parent,String id,CompoundTag data,List<SynchedEntityData.DataValue<?>> synced,double x,double y,double z,float yaw,float pitch,float bodyYaw,float headYaw,String policy,String syncedHash,boolean visibleExpected) {}
    record Snapshot(String adapter,String version,JsonObject extra,List<Node> nodes,boolean complete,String reason,boolean rootVisibleExpected) {}
    record Scene(List<Entity> independent,JsonObject report) {}
    static Snapshot capture(Entity root,boolean observed)throws Exception {
        String id=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(root.getType()).toString();var adapter=AppearanceAdapters.find(id);var nodes=new ArrayList<Node>();var extra=new JsonObject();boolean complete=id.startsWith("minecraft:")&&root.getClass().getName().startsWith("net.minecraft.");String reason=complete?"":"Unadapted mod appearance";String adapterId="mkb_export:standard",version="1";
        float referenceYaw=root instanceof net.minecraft.world.entity.LivingEntity living?living.yBodyRot:root.getYRot();
        var parts=new ArrayList<yagen.waitmydawn.mkb_export.api.EntityAppearanceAdapter.Part>();
        if(adapter!=null){adapterId=adapter.id();version=adapter.version();long start=System.nanoTime();var result=AppearanceAdapters.invoke(()->adapter.capture(root,observed));if(System.nanoTime()-start>AppearanceAdapters.policy().millis()*1000000L)throw new IllegalArgumentException("Adapter capture budget exceeded");AppearanceDataBudget.validate(result.extra());extra=result.extra().deepCopy();parts.addAll(result.parts());complete=result.complete();reason=result.reason();if(reason==null||reason.length()>4000)throw new IllegalArgumentException("Adapter reason exceeds budget");}
        else {var standard=Platform.parts(root);boolean dragon=root instanceof net.minecraft.world.entity.boss.enderdragon.EnderDragon;for(int i=0;i<standard.length;i++)parts.add(new yagen.waitmydawn.mkb_export.api.EntityAppearanceAdapter.Part("part_"+i,"root",standard[i],dragon?"PARENT_INCLUDED":"UNKNOWN"));if(standard.length>0&&!dragon){complete=false;reason="Standard parts have no declared visual policy";}}
        if(parts.size()>AppearanceAdapters.policy().parts()||extra.toString().length()>16384)throw new IllegalArgumentException("Composition exceeds budget");var keys=new HashSet<String>();keys.add("root");var depths=new HashMap<String,Integer>();depths.put("root",0);var objects=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());objects.add(root);
        for(var part:parts){if(!part.key().matches("[a-zA-Z0-9_.-]{1,80}")||!keys.contains(part.parent())||!keys.add(part.key())||!objects.add(part.entity())||part.entity().level()!=root.level()||part.entity() instanceof net.minecraft.world.entity.player.Player)throw new IllegalArgumentException("Invalid/cyclic composition relationship");int depth=depths.get(part.parent())+1;if(depth>128)throw new IllegalArgumentException("Composition depth exceeded");depths.put(part.key(),depth);if(!Set.of("INDEPENDENT","PARENT_INCLUDED","COLLISION_ONLY","UNKNOWN").contains(part.policy()))throw new IllegalArgumentException("Unknown part policy");if(part.policy().equals("UNKNOWN"))complete=false;
            var entity=part.entity();for(float angle:new float[]{referenceYaw,entity.getYRot(),entity.getXRot(),entity instanceof net.minecraft.world.entity.LivingEntity living?living.yBodyRot:0,entity instanceof net.minecraft.world.entity.LivingEntity living?living.yHeadRot:0})if(!Float.isFinite(angle))throw new IllegalArgumentException("Non-finite part rotation");Vec3 offset=Vec3.ZERO;if(part.policy().equals("INDEPENDENT")){var v=EntityLocalTransform.toRoot(entity.getX()-root.getX(),entity.getY()-root.getY(),entity.getZ()-root.getZ(),referenceYaw);offset=new Vec3(v.x(),v.y(),v.z());}if(!Double.isFinite(offset.lengthSqr())||offset.lengthSqr()>65536)throw new IllegalArgumentException("Invalid part position");CompoundTag data=part.policy().equals("INDEPENDENT")?EntitySamples.sanitized(entity):new CompoundTag();var synced=entity.getEntityData().getNonDefaultValues();synced=synced==null?List.<SynchedEntityData.DataValue<?>>of():List.copyOf(synced);
            String registry=part.policy().equals("INDEPENDENT")?net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString():id;nodes.add(new Node(part.key(),part.parent(),registry,data,synced,offset.x,offset.y,offset.z,net.minecraft.util.Mth.wrapDegrees(entity.getYRot()-referenceYaw),net.minecraft.util.Mth.wrapDegrees(entity.getXRot()),net.minecraft.util.Mth.wrapDegrees((entity instanceof net.minecraft.world.entity.LivingEntity living?living.yBodyRot:entity.getYRot())-referenceYaw),net.minecraft.util.Mth.wrapDegrees((entity instanceof net.minecraft.world.entity.LivingEntity living?living.yHeadRot:entity.getYRot())-referenceYaw),part.policy(),part.policy().equals("INDEPENDENT")?Platform.syncedFingerprint(synced,root.level().getServer()):"not-rendered",!entity.isInvisible()&&part.policy().equals("INDEPENDENT")));
        }return new Snapshot(adapterId,version,extra,List.copyOf(nodes),complete,reason,!root.isInvisible()&&(adapter==null||!AppearanceAdapters.invoke(()->adapter.rootIsContainer(root))));
    }
    static JsonObject description(Snapshot snapshot){var out=new JsonObject();out.addProperty("schemaVersion",1);out.addProperty("rootVisibleExpected",snapshot.rootVisibleExpected());out.addProperty("adapter",snapshot.adapter());out.addProperty("adapterVersion",snapshot.version());out.addProperty("status",snapshot.complete()?"COMPLETE":snapshot.adapter().equals("mkb_export:standard")?"UNVERIFIED":"PARTIAL");out.addProperty("reason",snapshot.reason());out.add("extra",snapshot.extra());var parts=new JsonArray();out.add("parts",parts);for(var node:snapshot.nodes()){var n=new JsonObject();n.addProperty("transformSpace","ROOT_LOCAL");n.addProperty("visibleExpected",node.visibleExpected());n.addProperty("syncedHash",node.syncedHash());n.addProperty("key",node.key());n.addProperty("parent",node.parent());n.addProperty("id",node.id());n.addProperty("policy",node.policy());n.addProperty("x",node.x());n.addProperty("y",node.y());n.addProperty("z",node.z());n.addProperty("yaw",node.yaw());n.addProperty("pitch",node.pitch());n.addProperty("bodyYaw",node.bodyYaw());n.addProperty("headYaw",node.headYaw());n.addProperty("dataHash",ContentDigest.sha256(node.data().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));parts.add(n);}return out;}
    static Scene restore(Entity root,Snapshot snapshot)throws Exception {
        var entities=new LinkedHashMap<String,Entity>();entities.put("root",root);var draw=new ArrayList<Entity>();
        for(var node:snapshot.nodes())if(node.policy().equals("INDEPENDENT")){var type=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.get(Platform.location(node.id().split(":",2)[0],node.id().split(":",2)[1]));var copy=type.create(root.level());if(copy==null||copy.getType()!=type)throw new IllegalArgumentException("Part has no independent factory: "+node.id());copy.load(node.data().copy());copy.getEntityData().assignValues(node.synced());copy.setPos(node.x(),node.y(),node.z());copy.setYRot(node.yaw());copy.yRotO=node.yaw();copy.setXRot(node.pitch());copy.xRotO=node.pitch();if(copy instanceof net.minecraft.world.entity.LivingEntity living){living.yBodyRot=living.yBodyRotO=node.bodyYaw();living.yHeadRot=living.yHeadRotO=node.headYaw();}entities.put(node.key(),copy);draw.add(copy);}
        var adapter=AppearanceAdapters.find(net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(root.getType()).toString());if(adapter==null?!snapshot.adapter().equals("mkb_export:standard"):!snapshot.adapter().equals(adapter.id())||!snapshot.version().equals(adapter.version()))throw new IllegalArgumentException("Captured appearance adapter identity/version is no longer available; capture again");if(adapter!=null){long start=System.nanoTime();AppearanceAdapters.invoke(()->{adapter.prepare(root,snapshot.extra().deepCopy(),Collections.unmodifiableMap(entities));return null;});if(System.nanoTime()-start>AppearanceAdapters.policy().millis()*1000000L)throw new IllegalArgumentException("Adapter preparation budget exceeded");}return new Scene(List.copyOf(draw),description(snapshot));
    }
}
